from pathlib import Path
import json,shutil,zipfile
R=Path(__file__).resolve().parents[2];out=R/'evaluation/reviewer-v6';out.mkdir(exist_ok=True)
cases=json.loads((R/'evaluation/v6/final.json').read_text())['cases'];selected=[{k:c[k] for k in ['id','source','question']} for c in cases if c['id'] in ['Q01','Q04','Q05','Q12','Q18','Q20']]
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>BenchSloth · independent source review</title><style>body{font:16px/1.7 system-ui;background:#f8f6f0;color:#17352e;max-width:900px;margin:auto;padding:25px}h1,h2{font-family:Georgia}article{padding:25px 0;border-top:1px solid #cbd2c7}li{font:13px/1.8 monospace;padding:5px}label{display:block;margin:12px 0}input,select,textarea,button{font:inherit;max-width:100%;padding:9px;background:#fffef9;border:1px solid #bfcbb7;color:inherit}textarea{width:100%;min-height:90px}button{cursor:pointer;min-height:44px}a{color:inherit}</style><h1>Evidence before interpretation.</h1><p>Independent source-only annotation. Please complete this before exploring model outputs. These are synthetic notes, not instructions to perform laboratory work. There is no answer key or system prediction in this page.</p><p>Mark whether each question is answerable, ambiguous or missing information. List the minimal source IDs supporting your decision and explain any disputed reference. No name, institution or contact details are needed. The browser saves nothing automatically. Export once finished and return the JSON privately to the project owner.</p><label>Pseudonymous reviewer code <input id="code" maxlength="30"></label><div id="cases"></div><button id="export">Export independent source judgments</button><p id="status" role="status"></p><p>Then complete the existing <a href="usability.html">timed usability comparison</a> and explore the <a href="demo/index.html">offline product</a>. Raw notes, numbered source and actual BenchSloth conditions rotate by participant code; record real elapsed time and mistakes. No AI reviewer result counts as human validation.</p><script>const cases=__CASES__,start=Date.now();for(const c of cases){const a=document.createElement('article');a.dataset.id=c.id;const h=document.createElement('h2');h.textContent=c.id+' / '+c.question;a.append(h);const ol=document.createElement('ol');for(const line of c.source.split('\\n')){const li=document.createElement('li');li.textContent=line;ol.append(li)}a.append(ol);for(const [label,key,type] of [['Your judgment','status','select'],['Supporting source IDs, comma separated','ids','input'],['Reason, uncertainty or corrections','notes','textarea']]){const l=document.createElement('label');l.textContent=label+' ';const n=document.createElement(type);n.dataset.key=key;if(type==='select')for(const value of ['Not reviewed','answer','ambiguous','not_available']){const o=document.createElement('option');o.textContent=value;n.append(o)}l.append(n);a.append(l)}document.getElementById('cases').append(a)}document.getElementById('export').onclick=()=>{const payload={instrument:'BenchSloth v0.6 blinded source QA',reviewer_code:document.getElementById('code').value,elapsed_ms:Date.now()-start,physical_work_performed:false,judgments:[...document.querySelectorAll('article')].map(a=>({id:a.dataset.id,...Object.fromEntries([...a.querySelectorAll('[data-key]')].map(n=>[n.dataset.key,n.value]))}))};const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='benchsloth-independent-qa-v6.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.getElementById('status').textContent='Exported. Send privately; no data was uploaded.'}</script></html>'''.replace('__CASES__',json.dumps(selected).replace('<','\\u003c'));(out/'labels.html').write_text(page)
for name in ['usability.html','followup.html']:
 source=R/'evaluation/reviewer-v5'/name
 if source.exists():shutil.copy2(source,out/name)
trial=(R/'static/reviewer-trial-v6.html').read_text();sources={k:json.loads((R/'static'/f'scenario-v5-{k}.json').read_text())['protocol'] for k in 'ABC'};(out/'usability.html').write_text(trial.replace('__SOURCES__',json.dumps(sources).replace('<','\\u003c')))
(out/'index.html').write_text('''<!doctype html><html lang="en"><meta charset="utf-8"><title>BenchSloth reviewer packet</title><body style="font:18px/1.8 system-ui;max-width:760px;margin:60px auto;padding:20px;background:#f8f6f0;color:#17352e"><h1>BenchSloth · independent review</h1><p>Complete <a href="labels.html">blinded source questions first</a>, then the <a href="usability.html">timed usability form</a> and <a href="demo/index.html">offline product</a>, then the <a href="followup.html">qualitative follow-up</a>. Export your real responses privately to the project owner. No install, account or model is required. The demo contains recorded model outputs; your timer and decisions run in the browser.</p><p>Do not perform a laboratory experiment. Do not enter identifying or institutional information. No participant results are included in this package.</p></body></html>''')
if (out/'demo').exists():shutil.rmtree(out/'demo')
shutil.copytree(R/'demo',out/'demo')
zip_path=R.parent/'BenchSloth_Reviewer_v0.6.zip'
with zipfile.ZipFile(zip_path,'w',zipfile.ZIP_DEFLATED) as z:
 for p in out.rglob('*'):
  if p.is_file():z.write(p,'BenchSloth_Reviewer_v0.6/'+str(p.relative_to(out)))
print(zip_path,zip_path.stat().st_size)
